async function api(path:string,body?:unknown,method?:string){const r=await fetch('/api/'+path,{method:method||(body===undefined?'GET':'POST'),headers:body===undefined?{}:{'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});let d:any;try{d=await r.json()}catch{throw Error('The server could not complete this request. Please retry.')}if(!r.ok){const e:any=Error(d.error||'Request failed');e.status=r.status;throw e}return d}
