function Avatar({p}:{p?:Partial<Person>|null}){return <span className="avatar">{p?.photo?<img src={p.photo} alt=""/>:p?.name?.slice(0,2).toUpperCase()||<UserRound size={18}/>}</span>}
function Empty({icon:Icon=Compass,title,children,action}:{icon?:any;title:string;children:ReactNode;action?:ReactNode}){return <div className="real-empty"><span className="empty-orbit"><Icon size={28}/></span><h3>{title}</h3><p>{children}</p>{action}</div>}
function Photo({p,className=''}:{p:Place;className?:string}){const [failed,setFailed]=useState(false);useEffect(()=>setFailed(false),[p.photoUrl]);return p.photoUrl&&!failed?<img className={className} src={p.photoUrl} alt={p.title} loading="lazy" onError={()=>setFailed(true)}/>:<div className={'photo-unavailable '+className}><MapPin size={25}/><span>Photo unavailable</span></div>}
function Attribution({p}:{p:Place}){return <div className="place-attribution"><span className={p.source==='Google Maps'?'google-maps-credit':''} translate="no">{p.source}</span>{p.photoMapsUrl&&<a href={p.photoMapsUrl} target="_blank" rel="noreferrer">View source photo</a>}{p.photoAuthors.map((a,i)=><a key={i} href={a.url||p.mapsUrl} target="_blank" rel="noreferrer">Photo: {a.name}</a>)}{p.attributions.map((a,i)=><a key={i} href={a.url} target="_blank" rel="noreferrer">{a.name}</a>)}</div>}

